ruleContent.content:
tag.ChapterContent@text<js>
var str = '';
for(var i=0; i<result.length; i++){
    var charCode = result.charCodeAt(i);
    if(charCode >= 65 && charCode <= 90){
        var newCharCode = charCode + 13;
        if (newCharCode > 90){
            newCharCode = newCharCode % 90 + 64;
        }
		charCode = newCharCode;
    }else if (97 <= charCode && charCode <= 122){
        var newCharCode = charCode + 13;
        if (newCharCode > 122){
            newCharCode = newCharCode % 122 + 96;
        }
		charCode = newCharCode;
    }
    str += String.fromCharCode(charCode);
};
result = java.base64Decoder(str);
</js>

